//! The one binding table: what each guest stub the engine binds crosses to, keyed (library, name). The guest's init binds every interceptable stub through `native_bridge_intercept_symbol(addr, library, name)` (vdso.rs); the libraries are the GL / window proxies (NBS `libnative_bridge_guest_*`: libEGL, libGLESv1_CM, libGLESv2, libGLESv3, libnativewindow), the NDK proxies (libandroid, libandroid_runtime, libjnigraphics: C3) and the guest libc.
//! `table` (generated by build.rs from the NBS stub lists, its binding lists and the EGL/GLES prototypes of two views) gives each (library, name) one entry: `Generic` (a symbol of a host library, through the generic crossing), `Shim` (a hand-written host side, [`shim`]), `Env(i)` (a JNI-typed NDK function: ndk.rs `call_env` maps the guest env) or `Trap(i)` (a named trap, aborting when called: unbound, or pending a binding class of GS2.2).
//! Every `Generic` symbol is looked up by `dlsym` on its host library's own handle, never `RTLD_DEFAULT`: the global scope can hold another definition of the name (Mesa's own GL exports, libatl_bionic's bionic names next to glibc's).

use std::collections::BTreeMap;
use std::ffi::{CStr, CString, c_void};
use std::sync::Mutex;

use super::objects::Class;
use super::{Active, active, unsupported};

/// The identity engine's table: the host arch's NBS libc stub list, every shim bound.
pub(super) mod identity {
    include!(concat!(env!("OUT_DIR"), "/bindings_table_identity.rs"));
}

/// The QEMU engine's table: the arm64 NBS libc stub list; the NDK shims bind as in identity's.
pub(crate) mod qemu {
    include!(concat!(env!("OUT_DIR"), "/bindings_table_qemu.rs"));
}

/// One engine's generated table.
struct Table {
    libs: &'static [Lib],
    trap_names: &'static [(&'static str, &'static str, &'static str)],
    traps: &'static [extern "C" fn()],
    env_rows: &'static [(&'static str, &'static str, usize)],
    env_fns: &'static [EnvFn],
    provider_soname: &'static str,
    prototypes: &'static [(&'static str, Class, Option<&'static str>)],
}

/// An `Entry::Env` row's host side (generated `env::<I>`): six int lanes in, one out.
type EnvFn = extern "C" fn(usize, usize, usize, usize, usize, usize) -> usize;

/// The table of the process's engine.
fn table() -> Table {
    match active() {
        Active::Identity => Table {
            libs: identity::LIBS,
            trap_names: identity::TRAP_NAMES,
            traps: identity::TRAPS,
            env_rows: identity::ENV_ROWS,
            env_fns: identity::ENV_FNS,
            provider_soname: identity::PROVIDER_SONAME,
            prototypes: identity::PROTOTYPES,
        },
        Active::Qemu => qemu_table(),
    }
}

/// The QEMU engine's table, whatever engine this process runs.
fn qemu_table() -> Table {
    Table {
        libs: qemu::LIBS,
        trap_names: qemu::TRAP_NAMES,
        traps: qemu::TRAPS,
        env_rows: qemu::ENV_ROWS,
        env_fns: qemu::ENV_FNS,
        provider_soname: qemu::PROVIDER_SONAME,
        prototypes: qemu::PROTOTYPES,
    }
}

/// The process engine's prototype descriptors (build.rs `PROTOTYPES`): name, return class, the QEMU lane refusal of its parameters (None: carried). Engine/proc.rs binds a host answer for a name with no row by one.
pub fn prototypes() -> &'static [(&'static str, Class, Option<&'static str>)] {
    table().prototypes
}

/// The host library a `Generic` entry's symbol is looked up in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Host {
    /// the host library of the guest proxy's soname in SYSTEM_LIB: the GL fronts (placed by `with_gl_driver`), libandroid and libjnigraphics (the ART root's libraries, host_art.rs `stage_art`)
    System,
    /// the process's bionic provider (`table::PROVIDER_SONAME`, loaded in every ART process): the bionic-only API glibc lacks
    Provider,
    /// glibc's `libc.so.6`
    Glibc,
}

/// What a stub binds to.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Entry {
    /// this symbol of that host library, whose result is of class `Class` (the proxy prototype's `ret`; integer for every libc row)
    Generic(Host, &'static str, Class),
    /// [`shim`] of the stub's name
    Shim,
    /// the env class (build.rs `ENV_SHIMS`): `table::ENV_FNS[i]` maps the guest `JNIEnv*` of `table::ENV_ROWS[i]` and calls that symbol of the host library (ndk.rs `call_env`)
    Env(usize),
    /// `table::TRAPS[i]`
    Trap(usize),
    /// an NBS stub variable (`uintptr_t name;`): it takes the value of this variable of that host library (opensl-es plan 2.2 item 6: `SL_IID_*`, a pointer to the host's IID; LP64 on both sides)
    Variable(Host, &'static str),
}

/// A guest library: its soname (what the guest's init passes to the intercept) and its stubs, in NBS list order.
pub struct Lib {
    pub soname: &'static str,
    pub stubs: &'static [(&'static str, Entry)],
}

/// JNI stubs per engine: one per slot of the largest JNI table (build.rs `OBJECT_STUBS`).
pub const OBJECT_STUBS: usize = identity::OBJECT_STUBS;
const _: () = assert!(identity::OBJECT_STUBS == qemu::OBJECT_STUBS);

/// One row of the table, for gates outside the engine (xtask `gl-proxies`, tests/qemu_gl.rs).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Binding {
    Generic {
        host: Host,
        symbol: &'static str,
        /// the result class the binding answers by (the prototype's `ret`)
        ret: Class,
    },
    Shim,
    /// the env class: `symbol` of the host library, its parameter `env` the mapped `JNIEnv*`
    Env {
        symbol: &'static str,
        env: usize,
    },
    /// why the stub traps: `unbound: …` (no host side), `pending: …` (a binding class still to build) or `refused: R-1 …` (QEMU: a prototype the lane image cannot carry, build.rs)
    Trap(&'static str),
    /// a stub variable taking the value of `symbol` in `host`
    Variable {
        host: Host,
        symbol: &'static str,
    },
}

/// Every (library, stub name, binding) of the process engine's table, in table order.
pub fn rows() -> impl Iterator<Item = (&'static str, &'static str, Binding)> {
    rows_of(table())
}

/// Every row of the QEMU engine's table, from any process (xtask `app-imports`: an APK's arm64 imports against it).
pub fn qemu_rows() -> impl Iterator<Item = (&'static str, &'static str, Binding)> {
    rows_of(qemu_table())
}

fn rows_of(t: Table) -> impl Iterator<Item = (&'static str, &'static str, Binding)> {
    t.libs.iter().flat_map(move |l| {
        l.stubs.iter().map(move |&(name, e)| {
            let b = match e {
                Entry::Generic(host, symbol, ret) => Binding::Generic { host, symbol, ret },
                Entry::Shim => Binding::Shim,
                Entry::Env(i) => Binding::Env {
                    symbol: t.env_rows[i].1,
                    env: t.env_rows[i].2,
                },
                Entry::Trap(i) => Binding::Trap(t.trap_names[i].2),
                Entry::Variable(host, symbol) => Binding::Variable { host, symbol },
            };
            (l.soname, name, b)
        })
    })
}

/// A trapped stub (each generated table's `trap::<I>`): aborts, naming the stub and why it is trapped.
fn trapped((lib, name, why): (&str, &str, &str)) {
    unsupported(&format!(
        "guest stub {lib}:{name} has no host binding ({why})"
    ))
}

/// The hand-written host side of `Entry::Shim` stub `name`: the one match over build.rs `SHIMS`, `QEMU_SHIMS` and `PROXY_SHIMS` (test `every_shim_has_an_arm`).
fn shim(name: &str) -> Option<usize> {
    Some(match name {
        "pthread_create" => super::intercepts::pthread_create as *const () as usize,
        "pthread_key_create" => super::intercepts::pthread_key_create as *const () as usize,
        "pthread_key_delete" => super::intercepts::pthread_key_delete as *const () as usize,
        "pthread_getattr_np" => super::intercepts::pthread_getattr_np as *const () as usize,
        "pthread_join" => super::intercepts::pthread_join as *const () as usize,
        "pthread_detach" => super::intercepts::pthread_detach as *const () as usize,
        "pthread_gettid_np" => super::intercepts::pthread_gettid_np as *const () as usize,
        // tr-first blocker 4: the handle-mapped glibc rows (build.rs `SHIMS`, intercepts.rs `BY_HANDLE`)
        n if super::intercepts::by_handle_fn(n).is_some() => super::intercepts::by_handle_fn(n)?,
        // Q7-7: QEMU table only (build.rs `QEMU_SHIMS`)
        "pthread_exit" => super::intercepts::pthread_exit as *const () as usize,
        "getaddrinfo" => super::netdb::getaddrinfo as *const () as usize,
        "freeaddrinfo" => super::netdb::freeaddrinfo as *const () as usize,
        "getnameinfo" => super::netdb::getnameinfo as *const () as usize,
        "__system_property_foreach" => super::provider::foreach as *const () as usize,
        "__system_property_read_callback" => super::provider::read_callback as *const () as usize,
        "sigaction" | "sigaction64" => super::signal::sigaction as *const () as usize,
        "slCreateEngine" => super::sles::create_engine as *const () as usize,
        // GS2.2 G1: the answer is a row's guest address or a bound host answer (proc.rs); build.rs `PROXY_SHIMS`
        "eglGetProcAddress" => super::proc::get_proc_address as *const () as usize,
        // Q5-8: the QEMU table's counted libc rows (build.rs `COUNTED_SHIMS`); identity never binds them
        #[cfg(feature = "crossing-count")]
        "memcpy" => crate::counters::memcpy as *const () as usize,
        #[cfg(feature = "crossing-count")]
        "memset" => crate::counters::memset as *const () as usize,
        #[cfg(feature = "crossing-count")]
        "memcmp" => crate::counters::memcmp as *const () as usize,
        _ => return None,
    })
}

/// What a stub binds to, with its host address and result class (a thunk is made of it by the caller).
pub enum Target {
    Host(usize, Class),
    /// a trap aborts, so its class is never read: integer
    Trap(usize),
    /// no host symbol: the stub stays unbound
    Absent,
}

impl Target {
    /// The host function the stub's thunk crosses to and its result class; None when absent.
    pub fn callee(self) -> Option<(usize, Class)> {
        match self {
            Target::Host(a, ret) => Some((a, ret)),
            Target::Trap(a) => Some((a, Class::Int)),
            Target::Absent => None,
        }
    }
}

/// The value stub variable `soname:name` takes (an `Entry::Variable` row: the host variable's word), counted in the library's report; None when the row is no variable or the host lacks the symbol.
pub fn variable(soname: &str, name: &str) -> Option<usize> {
    let lib = table().libs.iter().find(|l| l.soname == soname)?;
    let Some(&(_, Entry::Variable(host, sym))) = lib.stubs.iter().find(|(n, _)| *n == name) else {
        return None;
    };
    let value = symbol(host, lib.soname, sym).map(|at| {
        // SAFETY: a host data symbol of pointer size (`uintptr_t` on the guest side, LP64 both sides), in a library that stays loaded.
        unsafe { *(at as *const usize) }
    });
    report(lib, if value.is_some() { 0 } else { 3 });
    value
}

/// Per library, stubs by outcome: [bound to the host, unbound trap, pending trap, absent], printed once the library's list is complete.
static REPORT: Mutex<BTreeMap<&'static str, [usize; 4]>> = Mutex::new(BTreeMap::new());

#[allow(
    clippy::print_stderr,
    reason = "the startup report: one line per bound library, before any logger"
)]
fn report(lib: &'static Lib, outcome: usize) {
    let Ok(mut r) = REPORT.lock() else { return };
    let c = r.entry(lib.soname).or_insert([0; 4]);
    c[outcome] += 1;
    if c.iter().sum::<usize>() == lib.stubs.len() {
        eprintln!(
            "atl-native-bridge: bindings {}: {} bound to the host, {} unbound (trapped), {} pending a binding class (trapped), {} absent",
            lib.soname, c[0], c[1], c[2], c[3]
        );
    }
}

/// A handle per host library, opened once; 0 = not there.
static HANDLES: Mutex<BTreeMap<String, usize>> = Mutex::new(BTreeMap::new());

/// The handle of `host` for guest library `soname`; None when that host library is not there.
/// A system library is loaded by path from SYSTEM_LIB (the GL fronts are placed there by `with_gl_driver`; the loaded copy is returned when the process already has it, same inode); the provider and glibc are already loaded (`RTLD_NOLOAD`: no constructors run).
fn handle(host: Host, soname: &str) -> Option<usize> {
    let (path, flags) = match host {
        Host::System => (
            format!("{}/{soname}", atl_android_paths::SYSTEM_LIB),
            libc::RTLD_NOW,
        ),
        Host::Provider => (
            table().provider_soname.to_owned(),
            libc::RTLD_NOW | libc::RTLD_NOLOAD,
        ),
        Host::Glibc => ("libc.so.6".to_owned(), libc::RTLD_NOW | libc::RTLD_NOLOAD),
    };
    let mut handles = HANDLES.lock().ok()?;
    if let Some(&h) = handles.get(&path) {
        return (h != 0).then_some(h);
    }
    let c = CString::new(path.clone()).ok()?;
    // SAFETY: dlopen of a host library by path or soname; a front's constructors run here, on the calling host thread.
    let h = unsafe { libc::dlopen(c.as_ptr(), flags) } as usize;
    handles.insert(path, h);
    (h != 0).then_some(h)
}

/// `name` on `host`'s own handle (`soname`: the guest library, naming the front).
fn symbol(host: Host, soname: &str, name: &str) -> Option<usize> {
    let h = handle(host, soname)?;
    let c = CString::new(name).ok()?;
    // SAFETY: dlsym on a live handle with a NUL-terminated name.
    let p = unsafe { libc::dlsym(h as *mut c_void, c.as_ptr()) };
    (!p.is_null()).then_some(p as usize)
}

/// glibc's own `name` (intercepts.rs `by_handle` calls through it).
pub fn glibc_symbol(name: &str) -> Option<usize> {
    symbol(Host::Glibc, "", name)
}

/// The provider's own `name` (provider.rs shims call through it); None without the provider.
pub fn provider_symbol(name: &CStr) -> Option<usize> {
    symbol(Host::Provider, "", name.to_str().ok()?)
}

/// `name` on the system library `soname` of SYSTEM_LIB (ndk.rs shims call the host side of an NDK function through it); None when that library or symbol is not there.
pub fn system_symbol(soname: &str, name: &str) -> Option<usize> {
    symbol(Host::System, soname, name)
}

/// What `native_bridge_intercept_symbol(_, soname, name)` binds the guest stub to; None when `soname` is not in the table.
pub fn target(soname: &str, name: &str) -> Option<Target> {
    let table = table();
    let lib = table.libs.iter().find(|l| l.soname == soname)?;
    let entry = lib.stubs.iter().find(|(n, _)| *n == name).map(|&(_, e)| e);
    let found = |a: Option<usize>, ret: Class| match a {
        Some(a) => (Target::Host(a, ret), 0),
        None => (Target::Absent, 3),
    };
    let (t, outcome) = match entry {
        Some(Entry::Generic(host, sym, ret)) => found(symbol(host, lib.soname, sym), ret),
        Some(Entry::Shim) => found(shim(name), Class::Int),
        // its host symbol must be there too: the forwarder would abort at the first call otherwise
        Some(Entry::Env(i)) => found(
            system_symbol(lib.soname, table.env_rows[i].1).map(|_| table.env_fns[i] as usize),
            Class::Int,
        ),
        // a variable is never a stub: [`variable`] resolves it
        Some(Entry::Variable(..)) => (Target::Absent, 3),
        Some(Entry::Trap(i)) => {
            let why = table.trap_names[i].2;
            let outcome = if why.starts_with("unbound") { 1 } else { 2 };
            (Target::Trap(table.traps[i] as usize), outcome)
        }
        None => (Target::Absent, 3),
    };
    report(lib, outcome);
    Some(t)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_shim_has_an_arm() {
        for (lib, name, b) in rows() {
            if b == Binding::Shim {
                assert!(
                    shim(name).is_some(),
                    "{lib}:{name} is a Shim without an arm in bindings::shim"
                );
            }
        }
    }

    #[test]
    fn every_glibc_row_is_glibcs() {
        for (lib, name, b) in rows() {
            if let Binding::Generic {
                host: Host::Glibc,
                symbol: s,
                ..
            } = b
            {
                assert!(
                    symbol(Host::Glibc, lib, s).is_some(),
                    "{lib}:{name}: glibc lacks {s}"
                );
            }
        }
    }
}
